# Generated by build.py from recipe.yml for recipe dns-point-a-client-at-a-test-zone. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--cert', 'server.pem', '--key', 'server.key', '--dns-transport', 'https', 'dns://127.0.0.1:8080/', 'http://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --doh-url https://127.0.0.1:8080/dns-query --cacert server.pem http://api.example.test:8081/status.txt } finally { Stop-Process $server0 }
